('RA079-02','MR079-02','CN0073','existing_2025','existing_only',1,'核既有水的回用条件','先量化喷淋及地洗水，若有连续需求评估过滤及回用','conditional','新FCC项目无生产废水不能套用膜需求','既有2025工艺及排口监测','不把既有排口代表单独流股','流量、盐、金属、回用需求、处置费用','分流取样、比较简单过滤与膜','维持纳管及源头减量',NULL,NULL,NULL,NULL,NULL,NULL,'缺关键输入，不评分','2026-11-28'),
